          svg: `<svg viewBox="0 0 1100 1100" xmlns="http://www.w3.org/2000/svg"><rect width="1100" height="1100" fill="#1a1a2e"/><text x="550" y="60" text-anchor="middle" fill="#ffd700" font-size="30" font-weight="bold">The Chartwell Book Factory</text><circle cx="550" cy="500" r="60" fill="#ffd700" opacity="0.4" stroke="#ffd700" stroke-width="3"/><text x="550" y="495" text-anchor="middle" fill="#ffffff" font-size="16" font-weight="bold">Churchill</text><text x="550" y="515" text-anchor="middle" fill="#ffffff" font-size="14">dictates</text><circle cx="250" cy="280" r="80" fill="#6366f1" opacity="0.3" stroke="#6366f1" stroke-width="3"/><text x="250" y="270" text-anchor="middle" fill="#ffffff" font-size="14" font-weight="bold">Researchers</text><text x="250" y="290" text-anchor="middle" fill="#ffffff" font-size="13">Ashley, Deakin</text><text x="250" y="310" text-anchor="middle" fill="#ffffff" font-size="13">Wheldon, Marsh</text><circle cx="850" cy="280" r="80" fill="#10b981" opacity="0.3" stroke="#10b981" stroke-width="3"/><text x="850" y="270" text-anchor="middle" fill="#ffffff" font-size="14" font-weight="bold">Secretaries</text><text x="850" y="290" text-anchor="middle" fill="#ffffff" font-size="13">Hamblin, Hill</text><text x="850" y="310" text-anchor="middle" fill="#ffffff" font-size="13">Holmes (shifts)</text><circle cx="250" cy="720" r="80" fill="#f59e0b" opacity="0.3" stroke="#f59e0b" stroke-width="3"/><text x="250" y="710" text-anchor="middle" fill="#ffffff" font-size="14" font-weight="bold">Consultants</text><text x="250" y="730" fill="#ffffff" font-size="13" text-anchor="middle">Generals, classics</text><text x="250" y="750" fill="#ffffff" font-size="13" text-anchor="middle">scholars, lawyers</text><circle cx="850" cy="720" r="80" fill="#ec4899" opacity="0.3" stroke="#ec4899" stroke-width="3"/><text x="850" y="710" text-anchor="middle" fill="#ffffff" font-size="14" font-weight="bold">Publishers</text><text x="850" y="730" fill="#ffffff" font-size="13" text-anchor="middle">Cassell, Times</text><text x="850" y="750" fill="#ffffff" font-size="13" text-anchor="middle">Life, Daily Tel</text><line x1="320" y1="320" x2="490" y2="470" stroke="#6366f1" stroke-width="2" marker-end="url(#a7)"/><line x1="490" y1="470" x2="320" y2="650" stroke="#f59e0b" stroke-width="2" stroke-dasharray="3,3"/><line x1="610" y1="470" x2="780" y2="320" stroke="#10b981" stroke-width="2" stroke-dasharray="3,3"/><line x1="780" y1="650" x2="610" y2="470" stroke="#ec4899" stroke-width="2" marker-end="url(#a7)"/><defs><marker id="a7" markerWidth="10" markerHeight="10" refX="9" refY="3" orient="auto"><polygon points="0 0, 10 3, 0 6" fill="#ffd700"/></marker></defs><rect x="80" y="830" width="940" height="220" fill="#1a1a2e" stroke="#ffd700" stroke-width="2"/><text x="550" y="870" text-anchor="middle" fill="#ffd700" font-size="22" font-weight="bold">Productivity Output</text><text x="100" y="915" fill="#ffffff" font-size="16">Lifetime words published: 12-15 million (Dickens scale)</text><text x="100" y="945" fill="#ffffff" font-size="16">Marlborough biography: 1 million words, 4 volumes, 9 years</text><text x="100" y="975" fill="#ffffff" font-size="16">World Crisis: 2.1 million words, 6 volumes, 8 years</text><text x="100" y="1005" fill="#ffffff" font-size="16">Second World War: 1.6 million words, 6 volumes, 5 years</text><text x="100" y="1035" fill="#ffd700" font-size="16" font-weight="bold">English-Speaking Peoples: 1 million words, 4 volumes, 28 years</text></svg>`,
